using BenchmarkDotNet.Configs;
using BenchmarkDotNet.Environments;
using BenchmarkDotNet.Jobs;
using BenchmarkDotNet.Running;
using TextAnalysis;

var config = DefaultConfig.Instance
    .AddJob(Job.Default.WithRuntime(CoreRuntime.Core90).AsBaseline())
    .AddJob(Job.Default.WithRuntime(CoreRuntime.Core100));

BenchmarkRunner.Run<TextAnalyzerBenchmarks>(config, args);

[MemoryDiagnoser]
public class TextAnalyzerBenchmarks
{
    private TextAnalyzer _analyzer = null!;

    // A reasonably sized sample text to make benchmarks meaningful
    private const string SampleText =
        "The quick brown fox jumps over the lazy dog. " +
        "A benchmark is a test that measures the performance of a system or component. " +
        "Software engineering involves designing building testing and maintaining software applications. " +
        "Performance optimization requires careful measurement and analysis of bottlenecks. " +
        "The dotnet runtime provides a managed execution environment for applications. " +
        "Each new version of dotnet brings performance improvements across the board. " +
        "Hash sets provide constant time lookups for unique element tracking. " +
        "Histograms summarize distributions by counting occurrences in each bucket. " +
        "Average calculations divide the total sum by the number of elements. " +
        "Text analysis is a common task in natural language processing pipelines.";

    [GlobalSetup]
    public void Setup()
    {
        _analyzer = new TextAnalyzer(SampleText);
    }

    [Benchmark]
    public double AverageWordLength() => _analyzer.AverageWordLength();

    [Benchmark]
    public object WordLengthHistogram() => _analyzer.WordLengthHistogram();

    [Benchmark]
    public int UniqueWordCount() => _analyzer.UniqueWordCount();
}

